body.script:
(function () {
    var base = document.getElementById("lobby-script").dataset.base;
    var status = document.getElementById("status");
    var buttons = document.querySelectorAll("button");
    function beep() {
        try {
            var ctx = new (window.AudioContext || window.webkitAudioContext)();
            var o = ctx.createOscillator(); o.frequency.value = 880;
            o.connect(ctx.destination); o.start(); o.stop(ctx.currentTime + 0.2);
        } catch (e) { /* pas de son : le message reste à l'écran */ }
    }
    function show(text) {
        // Le message reste jusqu'au geste suivant (pas de délai imposé).
        status.textContent = text; status.style.display = "block"; beep();
    }
    function busy(on) { buttons.forEach(function (b) { b.disabled = on; }); }
    function post(path, params) {
        busy(true);
        return fetch(base + path, {method: "POST", headers: {"Content-Type": "application/json"},
            body: JSON.stringify({jsonrpc: "2.0", method: "call", params: params || {}})})
            .then(function (r) { return r.json(); })
            .then(function (r) { show((r.result && r.result.message) || "…"); })
            .catch(function () { show(document.getElementById("msg-retry").textContent); })
            .finally(function () { busy(false); });
    }
    document.querySelectorAll("button.call").forEach(function (b) {
        b.addEventListener("click", function () { post("/call", {resident_id: b.dataset.id}); });
    });
    document.getElementById("delivery").addEventListener("click", function () { post("/delivery"); });
    // Toutes les 5 minutes, l'annuaire se rafraîchit (un retrait, un départ,
    // un nouveau jumelage atteignent l'écran) ; jamais pendant une saisie,
    // et seulement si le serveur répond : une page d'erreur ne remplace pas
    // la page.
    var lastInput = 0;
    setInterval(function () {
        if (Date.now() - lastInput < 60000) { return; }
        fetch(location.href, {cache: "no-store"}).then(function (r) {
            if (r.status === 200) { location.reload(); }
            else if (r.status === 404) { show(document.getElementById("msg-unpaired").textContent); }
        }).catch(function () { /* serveur injoignable : on garde la page */ });
    }, 300000);
    document.getElementById("q").addEventListener("input", function (e) {
        lastInput = Date.now();
        var q = e.target.value.toLowerCase();
        document.querySelectorAll("#list li").forEach(function (li) {
            li.style.display = li.dataset.search.indexOf(q) === -1 ? "none" : "";
        });
    });
})();
